const cats = items.map(i => i.json);
const match = cats.find(c => String(c.name || '').trim().toLowerCase() === 'cigars');
if (!match) {
  const names = cats.map(c => c.name).join(', ');
  throw new Error('No category named "Cigars" found. Categories present: ' + names);
}
return [{ json: { category_id: match.category_id, category_name: match.name } }];

const report = $input.all().map(i => i.json);
const cigarItems = $('Fetch Cigar Items').all().map(i => i.json);
const cigarNumbers = new Set();
const cigarNames = new Set();
for (const it of cigarItems) {
  if (it.item_inactive === true) continue;
  if (it.item_number) cigarNumbers.add(String(it.item_number).trim().toLowerCase());
  if (it.item_id) cigarNumbers.add(String(it.item_id).trim().toLowerCase());
  if (it.name) cigarNames.add(String(it.name).trim().toLowerCase());
}
let rows = [];
for (const r of report) {
  if (r && r.data && Array.isArray(r.data.rows)) rows = rows.concat(r.data.rows);
  else if (r && Array.isArray(r.details)) rows = rows.concat(r.details);
  else if (r && r.data && Array.isArray(r.data)) rows = rows.concat(r.data);
}
function pick(obj, keys) {
  for (const k of keys) {
    for (const actual of Object.keys(obj)) {
      if (actual.toLowerCase().replace(/[^a-z]/g,'') === k) return obj[actual];
    }
  }
  return '';
}
function csvCell(v) {
  const s = String(v === null || v === undefined ? '' : v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
const out = ['sku,name,on_hand'];
let matched = 0;
let totalRows = rows.length;
for (const row of rows) {
  const num = String(pick(row, ['itemnumber','sku','item','number','itemid']) || '').trim().toLowerCase();
  const nm  = String(pick(row, ['name','itemname','description']) || '').trim().toLowerCase();
  const isCigar = (num && cigarNumbers.has(num)) || (nm && cigarNames.has(nm));
  if (!isCigar) continue;
  matched++;
  out.push([
    csvCell(pick(row, ['itemnumber','sku','item','number','itemid'])),
    csvCell(pick(row, ['name','itemname','description'])),
    csvCell(pick(row, ['quantity','onhand','instock','qty']))
  ].join(','));
}
const csv = out.join('\n') + '\n';
return [{
  json: {
    file_path: 'business-decisions-data/cigar-not-counted.csv',
    total_report_rows: totalRows,
    cigar_rows: matched,
    debug_first_row: rows.length ? JSON.stringify(rows[0]) : 'NO ROWS',
    commit_message: `Cigar not-counted list (${matched} cigars of ${totalRows} report rows)`,
    file_content: csv
  }
}];
